// WhatsApp click-to-chat: client reviews the message before opening WhatsApp.
(() => { const recipient = '916235311098'; const cabinRecipient = '919778311098'; function includesCabinCrew(data) { return data.getAll('scope').some(value => /cabin crew|complete bathroom service/i.test(String(value))) || /cabin[ _-]*crew/i.test(String(data.get('vision') || '')); } const labels = { project_type: 'Project type', location: 'Project location', bathrooms: 'Number of bathrooms', area: 'Approximate area per bathroom', budget: 'Overall project budget', timeline: 'Preferred start', client_role: 'Client role', scope: 'Help required', renovation_needs: 'Renovation priorities', plumbing_changes: 'Plumbing / layout changes', makeover_needs: 'Makeover priorities', keep_layout: 'Existing layout', construction_stage: 'Construction stage', floor_plan: 'Floor plan availability', vision: 'Style, materials and other priorities', name: 'Client name', email: 'Email', phone: 'Phone / WhatsApp', contact_method: 'Preferred contact method', contact_time: 'Good time to contact' }; function message(data) { const lines = ['Hello The Bathstore, I would like to discuss my bathroom project.', '', '*CLIENT PROJECT ENQUIRY*', '']; for (const [key, label] of Object.entries(labels)) { const values = data.getAll(key).map(value => String(value).trim()).filter(Boolean); if (values.length) lines.push(label + ': ' + values.join(', ')) } if (includesCabinCrew(data)) lines.push('', 'Cabin Crew design & build assistance requested.', 'Cabin Crew WhatsApp: https://wa.me/' + cabinRecipient); return lines.join('\n') } function link(text) { return 'https://wa.me/' + recipient + '?text=' + encodeURIComponent(text) } window.BathstoreWhatsApp = { labels, message, link, recipient, displayRecipient: '+91 62353 11098', includesCabinCrew, cabinLink(text) { return 'https://wa.me/' + cabinRecipient + '?text=' + encodeURIComponent(text) } }; })();
